class CircuitBreaker {
  constructor(timeout = 3000, threshold = 5) {
    this.failureCount = 0;
    this.threshold = threshold;
    this.state = 'CLOSED'; // CLOSED | OPEN | HALF_OPEN
    this.nextAttempt = Date.now();
  }
  async exec(fn) {
    if (this.state === 'OPEN' && Date.now() < this.nextAttempt) {
      throw new Error('[CIRCUIT_OPEN] Request fast-failed');
    }
    try {
      const res = await fn();
      this.reset();
      return res;
    } catch (err) {
      this.recordFailure();
      throw err;
    }
  }
}

// Idempotency guard using distributed cache key
async function processEvent(event) {
  const idempotencyKey = `evt_lock:${event.id}:${event.checksum}`;
  const acquired = await redis.set(idempotencyKey, 'LOCKED', 'NX', 'EX', 300);

  if (!acquired) {
    logger.warn(`[IDEMPOTENCY_SKIP] Event ${event.id} already processed`);
    return { status: 'DUPLICATE_IGNORED' };
  }

  return await executeBusinessLogic(event);
}
